<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import UniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue';
import UniNumberBox from '@dcloudio/uni-ui/lib/uni-number-box/uni-number-box.vue';
import { api, useIdentity } from '../../store';
import { ApiError, money, compactMoney, statusLabels, time, type Game, type Player, type Order, type Wallet, type Role, type ClubSettings } from '@stellar/core';
const identity=useIdentity();
const tab=ref('home'),selectedGame=ref('all'),search=ref(''),sort=ref('recommended'),statusFilter=ref('all');
const games=ref<Game[]>([]),players=ref<Player[]>([]),orders=ref<Order[]>([]),hall=ref<Order[]>([]),wallet=ref<Wallet|null>(null),settings=ref<ClubSettings|null>(null);
const loading=ref(true),refreshing=ref(false),busy=ref(false),error=ref('');
const sheet=ref<'roles'|'player'|'checkout'|'pay'|'order'|'refund'|'finish'|'help'|null>(null);
const selectedPlayer=ref<Player|null>(null),selectedOrder=ref<Order|null>(null),checkoutGame=ref('valorant'),region=ref(''),quantity=ref(1),note=ref(''),refundReason=ref(''),refundAmount=ref(0),finishNote=ref(''),agreed=ref(true);
const toast=ref('');let toastTimer:ReturnType<typeof setTimeout>;let interval:ReturnType<typeof setInterval>;
const isPlayer=computed(()=>identity.session?.role==='player');
const me=computed(()=>players.value.find(p=>p.id===identity.session?.playerId));
const displayPlayers=computed(()=>{let list=players.value.filter(p=>(selectedGame.value==='all'||p.gameIds.includes(selectedGame.value))&&[p.name,p.subtitle,...p.tags].join(' ').toLowerCase().includes(search.value.toLowerCase()));if(sort.value==='rating')list.sort((a,b)=>b.rating-a.rating);if(sort.value==='price')list.sort((a,b)=>a.price-b.price);return list;});
const displayOrders=computed(()=>orders.value.filter(o=>statusFilter.value==='all'||(statusFilter.value==='refund'?o.refundStatus==='pending':o.status===statusFilter.value)));
const currentGame=computed(()=>games.value.find(g=>g.id===checkoutGame.value));
const checkoutPrice=computed(()=>selectedPlayer.value?.price??Math.min(...players.value.filter(p=>p.gameIds.includes(checkoutGame.value)&&p.approved).map(p=>p.price)));
const gameName=(id:string)=>games.value.find(g=>g.id===id)?.name||id;
const gameColor=(id:string)=>games.value.find(g=>g.id===id)?.color||'#b0a2fc';
const activeCount=computed(()=>orders.value.filter(o=>['waiting','accepted','serving','confirming'].includes(o.status)).length);
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',2800);}
async function run(job:()=>Promise<void>){if(busy.value)return;busy.value=true;try{await job();}catch(e){notify(e instanceof Error?e.message:'操作失败，请重试');}finally{busy.value=false;}}
async function load(silent=false){if(refreshing.value)return;refreshing.value=true;if(!silent)loading.value=true;try{if(!identity.session)await identity.login('boss');const [g,p,o,s]=await Promise.all([api.games(),api.players(),api.orders(),api.settings()]);games.value=g;players.value=p;orders.value=o;settings.value=s;if(isPlayer.value){[hall.value,wallet.value]=await Promise.all([api.orders({scope:'hall'}),api.wallet()]);}if(selectedOrder.value){selectedOrder.value=orders.value.find(o=>o.id===selectedOrder.value?.id)||selectedOrder.value;}error.value='';}catch(e){if(e instanceof ApiError&&e.code===401){await identity.login(isPlayer.value?'player':'boss');refreshing.value=false;await load(silent);return;}error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;refreshing.value=false;}}
async function switchRole(role:Role){await run(async()=>{await identity.login(role);sheet.value=null;tab.value='home';statusFilter.value='all';await load();notify(role==='boss'?'已进入老板视角 · 林序':'已进入打手视角 · 岚');});}
function openPlayer(p:Player){selectedPlayer.value=p;sheet.value='player';}
function book(p?:Player){selectedPlayer.value=p||null;checkoutGame.value=p?.gameIds[0]||(selectedGame.value==='all'?'valorant':selectedGame.value);region.value=games.value.find(g=>g.id===checkoutGame.value)?.regions[0]||'';quantity.value=1;note.value='';agreed.value=true;sheet.value='checkout';}
function selectCheckoutGame(id:string){checkoutGame.value=id;region.value=games.value.find(g=>g.id===id)?.regions[0]||'';}
async function createOrder(){await run(async()=>{if(!agreed.value){notify('请先阅读并同意服务说明');return;}selectedOrder.value=await api.createOrder({gameId:checkoutGame.value,region:region.value,quantity:quantity.value,playerId:selectedPlayer.value?.id,note:note.value});await load(true);sheet.value='pay';});}
function openOrder(o:Order){selectedOrder.value=o;sheet.value='order';}
async function action(action:string,o=selectedOrder.value,body?:unknown){if(!o)return;await run(async()=>{const result=await api.act(o.id,action,body);selectedOrder.value=result;await load(true);if(action==='pay'){sheet.value='order';tab.value='orders';notify('模拟支付成功，正在等待队友接单');}else if(action==='accept'){sheet.value='order';tab.value='orders';notify('接单成功，请及时开始服务');}else{if(action==='finish'||action==='refund')sheet.value='order';notify(({start:'服务已开始',finish:'已提交，等待老板确认',confirm:'订单已完成，谢谢你的信任',cancel:'订单已取消',refund:'退款申请已提交'} as Record<string,string>)[action]||'操作成功');}});}
function refund(o:Order){selectedOrder.value=o;refundReason.value='';refundAmount.value=o.amount/100;sheet.value='refund';}
function finish(o:Order){selectedOrder.value=o;finishNote.value='';sheet.value='finish';}
async function availability(){await run(async()=>{await api.availability(!me.value?.available);await load(true);notify(me.value?.available?'已开启接单':'已切换为休息状态');});}
function navigate(next:string){tab.value=next;statusFilter.value='all';}
function goAdmin(){// #ifdef H5
  window.open('/admin/','_blank');
  // #endif
}
onMounted(async()=>{await load();interval=setInterval(()=>load(true),10000);});
onUnmounted(()=>{clearInterval(interval);clearTimeout(toastTimer);});
</script>

<template>
  <view class="mobile-app">
    <view class="topbar">
      <view class="wordmark"><view class="star-mark">✳</view><view>{{settings?.name||'星曜电竞'}}<text>STELLAR CLUB</text></view></view>
      <button class="role-pill" @tap="sheet='roles'"><view class="live-dot"/>{{isPlayer?'打手端':'老板端'}}<uni-icons type="bottom" color="#bfc1ca" :size="11"/></button>
      <button class="icon-btn" aria-label="通知与帮助" @tap="sheet='help'"><uni-icons type="notification" color="#d8dae3" :size="22"/><view class="notification-dot"/></button>
    </view>
    <view class="demo-strip"><view class="demo-dot"/> 演示模式 · 不产生真实扣款 <button @tap="sheet='roles'">切换身份</button></view>
    <view v-if="error" class="error-box">{{error}}<button @tap="load()">重新加载</button></view>
    <view v-if="loading" class="loading"><view class="loading-ring"/> 正在加载…</view>

    <view v-else-if="tab==='home' && !isPlayer" class="home content">
      <view class="home-intro"><view><view class="home-title">找到合拍的队友</view><view class="home-caption">选你喜欢的游戏，快乐一起玩。</view></view><view class="intro-emblem">✳</view></view>
      <view class="search-box"><uni-icons type="search" color="#929aaa" :size="20"/><input v-model="search" placeholder="搜索队友、游戏或擅长标签" placeholder-class="placeholder"/><button v-if="search" aria-label="清空搜索" @tap="search=''"><uni-icons type="clear" color="#929aaa" :size="17"/></button></view>
      <view class="quick-book"><view><view class="quick-book-title">不想挑？让我们帮你匹配</view><view class="quick-book-copy">选好游戏，即可发起大厅订单</view></view><button class="quick-book-button" @tap="book()">快速下单 <uni-icons type="arrow-right" color="#1b2412" :size="15"/></button></view>
      <view class="section-top"><view class="section-title">选择游戏</view><button v-if="selectedGame!=='all'" class="filter-clear" @tap="selectedGame='all'">查看全部</button><text v-else class="section-hint">点击筛选队友</text></view>
      <view class="game-grid"><button v-for="g in games" :key="g.id" class="game-card" :class="{selected:selectedGame===g.id}" :style="{'--game-color':g.color}" @tap="selectedGame=selectedGame===g.id?'all':g.id"><view class="game-visual"><view class="game-glyph">{{g.short}}</view></view><view class="game-name">{{g.name}}</view><view class="game-online"><view class="live-dot"/>{{players.filter(p=>p.available&&p.gameIds.includes(g.id)).length}} 位在线</view></button></view>
      <view class="section-top team-top"><view class="section-title">推荐队友 <text>{{displayPlayers.length}}</text></view><button class="refresh-link" @tap="load(true)"><uni-icons type="refreshempty" color="#929aaa" :size="15"/> 刷新</button></view>
      <view class="filter-row"><view class="filter-tabs"><button :class="{active:sort==='recommended'}" @tap="sort='recommended'">综合推荐</button><button :class="{active:sort==='rating'}" @tap="sort='rating'">好评优先</button><button :class="{active:sort==='price'}" @tap="sort='price'">价格优先</button></view></view>
      <view class="player-list"><view v-for="p in displayPlayers" :key="p.id" class="player-card" @tap="openPlayer(p)"><view class="portrait" :style="{'--portrait-color':p.color}"><text>{{p.avatar}}</text></view><view class="player-info"><view class="player-name">{{p.name}}<view class="verified">✓</view><view class="player-availability" :class="{rest:!p.available}"><view class="live-dot"/>{{p.available?'可接单':'休息中'}}</view></view><view class="player-subtitle">{{p.subtitle}}</view><view class="tags"><text v-for="tag in p.tags" :key="tag">{{tag}}</text></view><view class="player-bottom"><view class="rating">★ {{p.rating}}<text> · {{p.completed}} 单</text></view><view class="price">¥{{compactMoney(p.price)}}<text>/小时</text></view></view></view></view></view>
      <view v-if="!displayPlayers.length" class="empty"><uni-icons type="search" color="#768196" :size="35"/><view>暂时没有匹配的队友</view><text>试试其他游戏或搜索关键词</text><button @tap="search='';selectedGame='all'">清除筛选</button></view>
      <view class="service-note"><view class="small-star">✳</view><view>安心下单，认真服务。<text>{{settings?.announcement||'有问题，俱乐部一直在你身边。'}}</text></view><button @tap="sheet='help'">联系客服</button></view>
    </view>

    <view v-else-if="tab==='home' && isPlayer" class="content player-home">
      <view class="page-heading"><view><view class="greeting">READY WHEN YOU ARE</view><view class="page-title">接单大厅<text class="lime-dot"/></view></view><button class="availability-toggle" :class="{off:!me?.available}" @tap="availability"><view class="live-dot"/>{{me?.available?'接单中':'休息中'}}<uni-icons type="loop" :size="14" color="#c8ed8a"/></button></view>
      <view class="player-welcome"><view class="welcome-kicker">{{identity.session?.name}}，今天也一起打好每一局</view><view class="wallet-big">¥{{money(wallet?.total||0)}}<text>累计已完成报酬</text></view><view class="welcome-stats"><view><text>{{activeCount}}</text>进行中订单</view><view><text>{{hall.length}}</text>可接订单</view><view><text>{{me?.rating||'4.98'}}</text>服务评分</view></view></view>
      <view class="notice"><uni-icons type="info" color="#c0b4ff" :size="17"/><text>仅展示与你技能匹配的订单。接单后请及时开始服务。</text></view>
      <view class="section-top"><view class="section-title">适合你的订单<text>AVAILABLE MATCHES</text></view><button class="refresh-link" @tap="load(true)"><uni-icons type="refreshempty" :size="14" color="#a0a3af"/> 刷新</button></view>
      <view v-for="o in hall" :key="o.id" class="job-card"><view class="order-top"><view class="game-label" :style="{color:gameColor(o.gameId)}"><view class="mini-game" :style="{background:gameColor(o.gameId)+'20'}">{{games.find(g=>g.id===o.gameId)?.short}}</view>{{o.gameName}}</view><text class="status waiting">待接单</text></view><view class="job-title">{{o.bossName}}的{{o.quantity}}小时陪玩订单</view><view class="muted">{{o.region}} <text class="separator">/</text> {{o.preferredPlayerName?'指定 '+o.preferredPlayerName:'大厅订单'}}</view><view class="job-note">“{{o.note||'一起快乐开黑，期待默契队友。'}}”</view><view class="job-bottom"><view class="earning">¥{{money(o.earnings)}}<text>预计报酬</text></view><button class="primary compact" :disabled="busy||!me?.available" @tap="action('accept',o)">立即接单 <uni-icons type="arrow-right" :size="16" color="#11150c"/></button></view></view>
      <view v-if="!hall.length" class="empty"><uni-icons type="flag" color="#686c7c" :size="40"/><view>暂时没有适合的订单</view><text>先休息一下，新的默契正在路上</text></view>
    </view>

    <view v-else-if="tab==='orders'" class="content orders-page"><view class="page-heading"><view><view class="greeting">EVERY GAME COUNTS</view><view class="page-title">我的订单<text class="count-badge">{{orders.length}}</text></view></view><button class="icon-btn" aria-label="刷新订单" @tap="load(true)"><uni-icons type="refreshempty" color="#bec1ce" :size="24"/></button></view><scroll-view scroll-x class="order-tabs"><view class="order-tabs-inner"><button v-for="filter in [{id:'all',label:'全部'},{id:isPlayer?'accepted':'unpaid',label:isPlayer?'待开始':'待付款'},{id:'waiting',label:'待接单'},{id:'serving',label:'服务中'},{id:'confirming',label:'待确认'},{id:'completed',label:'已完成'},{id:'refund',label:'售后'}]" :key="filter.id" :class="{active:statusFilter===filter.id}" @tap="statusFilter=filter.id">{{filter.label}}</button></view></scroll-view>
      <view v-for="o in displayOrders" :key="o.id" class="order-card" @tap="openOrder(o)"><view class="order-top"><view class="game-label"><view class="mini-game" :style="{background:gameColor(o.gameId)+'20',color:gameColor(o.gameId)}">{{games.find(g=>g.id===o.gameId)?.short}}</view>{{o.gameName}}</view><text class="status" :class="o.refundStatus==='pending'?'refund':o.status">{{o.refundStatus==='pending'?'售后处理中':statusLabels[o.status]}}</text></view><view class="order-person"><view class="small-avatar" :style="{background:players.find(p=>p.id===o.playerId)?.color||'#b3b5c8'}">{{isPlayer?o.bossName.slice(0,1):(o.playerName||o.preferredPlayerName||'?').slice(0,1)}}</view><view><view class="order-person-name">{{isPlayer?o.bossName:o.playerName||o.preferredPlayerName||'等待默契队友'}}</view><view class="muted">{{o.region}} · {{o.quantity}} 小时</view></view><view class="order-amount">¥{{money(isPlayer?o.earnings:o.amount)}}<text>{{isPlayer?'预计报酬':'订单金额'}}</text></view></view><view class="order-meta"><text>{{time(o.createdAt)}}</text><text>{{o.id}}</text></view><view class="order-actions" @tap.stop><button class="secondary small" @tap="openOrder(o)">订单详情</button><button v-if="!isPlayer&&o.status==='unpaid'" class="primary small" @tap="selectedOrder=o;sheet='pay'">去付款</button><button v-if="!isPlayer&&o.status==='confirming'&&o.refundStatus!=='pending'" class="primary small" @tap="action('confirm',o)">确认完成</button><button v-if="isPlayer&&o.status==='accepted'&&o.refundStatus!=='pending'" class="primary small" @tap="action('start',o)">开始服务</button><button v-if="isPlayer&&o.status==='serving'&&o.refundStatus!=='pending'" class="primary small" @tap="finish(o)">提交完成</button></view></view>
      <view v-if="!displayOrders.length" class="empty"><uni-icons type="list" color="#686c7c" :size="42"/><view>这里还没有订单</view><text>新的游戏故事，从一次组队开始</text><button class="primary compact" @tap="navigate('home')">{{isPlayer?'去接单大厅':'寻找队友'}}</button></view>
    </view>

    <view v-else-if="tab==='wallet' && isPlayer" class="content"><view class="greeting">YOUR EFFORT, REWARDED</view><view class="page-title">我的报酬</view><view class="income-card"><view class="muted">累计已完成报酬（元）</view><view class="income-amount">{{money(wallet?.total||0)}}</view><view class="income-row"><view>待结算<text>¥{{money(wallet?.pending||0)}}</text></view><view>已结算<text>¥{{money(wallet?.settled||0)}}</text></view></view></view><view class="notice"><uni-icons type="info" color="#c0b4ff" :size="18"/><text>报酬已扣除订单约定的平台服务费。售后订单暂缓结算，由财务按批次处理。</text></view><view class="section-top"><view class="section-title">报酬明细</view><text class="muted">{{wallet?.orders.length||0}} 笔</text></view><view v-for="o in wallet?.orders" :key="o.id" class="income-item" @tap="openOrder(o)"><view class="mini-game" :style="{color:gameColor(o.gameId),background:gameColor(o.gameId)+'20'}">{{games.find(g=>g.id===o.gameId)?.short}}</view><view class="income-item-info"><view>{{o.gameName}} · {{o.quantity}} 小时</view><text>{{time(o.createdAt)}} · {{o.refundStatus==='pending'?'售后冻结':o.settlementId?'已进入结算批次':'待结算'}}</text></view><view class="income-plus">+{{money(o.earnings)}}</view></view><view v-if="!wallet?.orders.length" class="empty">完成第一笔订单后，报酬会出现在这里。</view><view class="section-top" v-if="wallet?.settlements.length"><view class="section-title">结算记录</view></view><view v-for="s in wallet?.settlements" :key="s.id" class="income-item"><view class="income-item-info"><view>{{s.status==='paid'?'已模拟付款':'财务待付款'}}</view><text>{{s.orderIds.length}} 笔 · {{time(s.createdAt)}}</text></view><view>¥{{money(s.amount)}}</view></view></view>

    <view v-else class="content profile-page"><view class="greeting">YOUR SPACE, YOUR PACE</view><view class="profile-header"><view class="profile-avatar">{{identity.session?.name.slice(0,1)}}</view><view><view class="profile-name">{{identity.session?.name}}<view class="profile-level">{{isPlayer?'认证打手':'星曜玩家'}}</view></view><view class="muted">{{isPlayer?'每一次认真，都有人记得':'欢迎来到你的快乐补给站'}}</view></view></view><view class="profile-stats"><view><text>{{orders.length}}</text>全部订单</view><view><text>{{activeCount}}</text>进行中</view><view><text>{{orders.filter(o=>o.status==='completed').length}}</text>已完成</view></view><view class="profile-menu"><button @tap="navigate('orders')"><uni-icons type="list" :size="21" color="#bdb5f5"/><text>我的订单</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button v-if="isPlayer" @tap="navigate('wallet')"><uni-icons type="wallet" :size="21" color="#bdb5f5"/><text>报酬与结算</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='roles'"><uni-icons type="loop" :size="21" color="#bdb5f5"/><text>切换演示身份</text><text class="menu-trailing">{{isPlayer?'打手端':'老板端'}}</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='help'"><uni-icons type="headphones" :size="21" color="#bdb5f5"/><text>联系俱乐部客服</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="goAdmin"><uni-icons type="staff" :size="21" color="#bdb5f5"/><text>员工运营工作台</text><text class="menu-trailing">PC 端</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button></view><view class="profile-about"><view class="small-star">✳</view><text>STELLAR CLUB</text><view>好游戏，好队友。</view><text class="version">交互体验版 v1.0 · 模拟数据仅保存在当前浏览器</text></view></view>

    <view class="bottom-nav"><button :class="{active:tab==='home'}" @tap="navigate('home')"><uni-icons :type="isPlayer?'flag':'home'" :color="tab==='home'?'#d9fd88':'#777c8b'" :size="23"/><text>{{isPlayer?'接单大厅':'找队友'}}</text><view v-if="tab==='home'" class="nav-indicator"/></button><button :class="{active:tab==='orders'}" @tap="navigate('orders')"><view class="nav-icon"><uni-icons type="list" :color="tab==='orders'?'#d9fd88':'#777c8b'" :size="24"/><view v-if="activeCount" class="nav-badge">{{activeCount}}</view></view><text>订单</text><view v-if="tab==='orders'" class="nav-indicator"/></button><button v-if="isPlayer" :class="{active:tab==='wallet'}" @tap="navigate('wallet')"><uni-icons type="wallet" :color="tab==='wallet'?'#d9fd88':'#777c8b'" :size="23"/><text>报酬</text><view v-if="tab==='wallet'" class="nav-indicator"/></button><button :class="{active:tab==='me'}" @tap="navigate('me')"><uni-icons type="person" :color="tab==='me'?'#d9fd88':'#777c8b'" :size="23"/><text>我的</text><view v-if="tab==='me'" class="nav-indicator"/></button></view>

    <view v-if="sheet" class="sheet-mask" @tap="sheet=null"><view class="sheet" :class="{'sheet-tall':['order','checkout','player'].includes(sheet)}" @tap.stop><view class="sheet-handle"/><button class="sheet-close" aria-label="关闭弹窗" @tap="sheet=null"><uni-icons type="closeempty" color="#a4a8b7" :size="24"/></button>
      <view v-if="sheet==='roles'" class="sheet-content"><view class="eyebrow">CHOOSE YOUR SIDE</view><view class="sheet-title">选择你的身份</view><view class="sheet-sub">模拟授权，无需真实微信或手机号。</view><button class="role-card" :class="{chosen:!isPlayer}" :disabled="busy" @tap="switchRole('boss')"><view class="role-icon boss-icon"><uni-icons type="person" color="#d9fd88" :size="27"/></view><view><view>我是老板<text>林序 · 体验账号</text></view><text>发现队友，下单开启快乐游戏</text></view><uni-icons type="arrow-right" color="#a5a8b5" :size="20"/></button><button class="role-card" :class="{chosen:isPlayer}" :disabled="busy" @tap="switchRole('player')"><view class="role-icon"><uni-icons type="flag" color="#c5b8ff" :size="27"/></view><view><view>我是打手<text>岚 · 认证打手</text></view><text>接取订单，让实力获得认可</text></view><uni-icons type="arrow-right" color="#a5a8b5" :size="20"/></button><view class="sheet-footnote">点击身份即完成模拟微信授权。真实登录将在后端接入阶段替换。</view></view>
      <view v-else-if="sheet==='player' && selectedPlayer" class="sheet-content"><view class="player-detail-header"><view class="portrait large" :style="{'--portrait-color':selectedPlayer.color}"><view class="portrait-halo"/><view class="portrait-head"/><view class="portrait-body"/><text>{{selectedPlayer.avatar}}</text></view><view><view class="sheet-title">{{selectedPlayer.name}} <text class="verified">✓</text></view><view class="sheet-sub">{{selectedPlayer.subtitle}}</view><view class="tags"><text v-for="t in selectedPlayer.tags" :key="t">{{t}}</text></view></view></view><view class="detail-stats"><view><text>{{selectedPlayer.rating}}</text>服务评分</view><view><text>{{selectedPlayer.completed}}</text>已完成订单</view><view><text>{{selectedPlayer.available?'在线':'休息'}}</text>接单状态</view></view><view class="form-label">关于我</view><view class="detail-bio">{{selectedPlayer.bio}}</view><view class="form-label">支持的游戏</view><view class="tags game-tags"><text v-for="id in selectedPlayer.gameIds" :key="id">{{gameName(id)}}</text></view><view class="service-promise"><uni-icons type="auth" color="#c2b6ff" :size="18"/> 已通过俱乐部审核 · 服务问题可申请售后</view><view class="sheet-bottom"><view class="price large-price">¥{{compactMoney(selectedPlayer.price)}}<text>/小时</text></view><button class="primary" :disabled="!selectedPlayer.available||isPlayer" @tap="book(selectedPlayer)">{{selectedPlayer.available?'邀请一起玩':'队友休息中'}} <uni-icons type="arrow-right" color="#11150c" :size="17"/></button></view></view>
      <view v-else-if="sheet==='checkout'" class="sheet-content"><view class="eyebrow">LET'S PLAY TOGETHER</view><view class="sheet-title">确认订单</view><view class="sheet-sub">{{selectedPlayer?'指定队友 · '+selectedPlayer.name:'大厅订单 · 由匹配打手接单'}}</view><view class="form-label">选择游戏</view><view class="choice-row"><button v-for="g in games.filter(g=>!selectedPlayer||selectedPlayer.gameIds.includes(g.id))" :key="g.id" :class="{selected:checkoutGame===g.id}" @tap="selectCheckoutGame(g.id)">{{g.name}}</button></view><view class="form-label">游戏区服</view><view class="choice-row"><button v-for="r in currentGame?.regions" :key="r" :class="{selected:region===r}" @tap="region=r">{{r}}</button></view><view class="form-inline"><view><view class="form-label">服务时长</view><view class="muted">¥{{compactMoney(checkoutPrice)}} / 小时</view></view><view class="quantity-control"><uni-number-box v-model="quantity" :min="1" :max="8" background="#2b2d39" color="#f5f5f5"/><text>小时</text></view></view><view class="form-label">给队友留句话<text>选填</text></view><textarea v-model="note" class="text-area" placeholder="游戏偏好、希望开始的时间，都可以告诉队友…" :maxlength="200"/><view class="order-price-line"><text>服务金额</text><text>¥{{money(checkoutPrice*quantity)}}</text></view><view class="order-price-line muted"><text>平台保障</text><text>已包含</text></view><button class="agreement" @tap="agreed=!agreed"><view class="checkmark" :class="{checked:agreed}">{{agreed?'✓':''}}</view><text>我已了解：按小时计费，服务问题可申请售后。</text></button><view class="sheet-bottom"><view class="total-price"><text>合计</text>¥{{money(checkoutPrice*quantity)}}</view><button class="primary" :disabled="busy" @tap="createOrder">{{busy?'正在提交…':'提交订单'}} <uni-icons type="arrow-right" color="#11150c" :size="17"/></button></view></view>
      <view v-else-if="sheet==='pay' && selectedOrder" class="sheet-content payment-sheet"><view class="pay-icon"><uni-icons type="weixin" :size="42" color="#72e2a0"/></view><view class="sheet-title">微信支付 · 模拟收银台</view><view class="sheet-sub">{{selectedOrder.gameName}} · {{selectedOrder.quantity}} 小时</view><view class="pay-amount"><text>¥</text>{{money(selectedOrder.amount)}}</view><view class="pay-order">{{selectedOrder.id}}</view><view class="simulation-note">这是交互演示，不会发起真实扣款。<br/>确认后将模拟支付成功并更新订单状态。</view><button class="primary full" :disabled="busy" @tap="action('pay')">{{busy?'正在模拟支付…':'确认模拟支付'}}</button><button class="text-button" @tap="sheet='order';tab='orders'">稍后支付</button></view>
      <view v-else-if="sheet==='order' && selectedOrder" class="sheet-content"><view class="eyebrow">ORDER DETAILS</view><view class="sheet-title">{{selectedOrder.refundStatus==='pending'?'售后处理中':statusLabels[selectedOrder.status]}}</view><view class="sheet-sub">{{selectedOrder.id}}</view><view class="detail-order-game"><view class="mini-game big" :style="{background:gameColor(selectedOrder.gameId)+'22',color:gameColor(selectedOrder.gameId)}">{{games.find(g=>g.id===selectedOrder?.gameId)?.short}}</view><view><view>{{selectedOrder.gameName}}</view><text>{{selectedOrder.region}} · {{selectedOrder.quantity}} 小时</text></view><view class="detail-order-price">¥{{money(selectedOrder.amount)}}</view></view><view class="detail-row"><text>老板</text><text>{{selectedOrder.bossName}}</text></view><view class="detail-row"><text>服务队友</text><text>{{selectedOrder.playerName||selectedOrder.preferredPlayerName||'等待接单'}}</text></view><view class="detail-row"><text>服务单价</text><text>¥{{money(selectedOrder.unitPrice)}} / 小时</text></view><view v-if="isPlayer" class="detail-row"><text>预计报酬（已扣服务费）</text><text class="lime">¥{{money(selectedOrder.earnings)}}</text></view><view v-if="selectedOrder.note" class="detail-note">{{selectedOrder.note}}</view><view v-if="selectedOrder.refundStatus!=='none'" class="refund-info"><view>售后状态：{{selectedOrder.refundStatus==='pending'?'待审核':selectedOrder.refundStatus==='refunded'?'已模拟退款':'未通过'}}</view><text>申请 ¥{{money(selectedOrder.refundAmount||0)}} · {{selectedOrder.refundReason}}</text><text v-if="selectedOrder.refundReviewNote">审核说明：{{selectedOrder.refundReviewNote}}</text></view><view class="form-label">订单动态</view><view class="timeline"><view v-for="(e,i) in selectedOrder.timeline" :key="i" class="timeline-item"><view class="timeline-dot"/><view><view>{{e.label}}</view><text>{{time(e.at)}} · {{e.actor}}</text><view v-if="e.note" class="timeline-note">{{e.note}}</view></view></view></view><view class="detail-actions"><button class="secondary" @tap="sheet='help'">联系客服</button><template v-if="!isPlayer"><button v-if="selectedOrder.status==='unpaid'" class="secondary" :disabled="busy" @tap="action('cancel')">取消订单</button><button v-if="selectedOrder.status==='unpaid'" class="primary" @tap="sheet='pay'">去付款</button><button v-if="selectedOrder.status==='confirming'&&selectedOrder.refundStatus!=='pending'" class="primary" :disabled="busy" @tap="action('confirm')">确认完成</button><button v-if="selectedOrder.paidAt&&selectedOrder.status!=='cancelled'&&['none','rejected'].includes(selectedOrder.refundStatus)&&!selectedOrder.settlementId" class="secondary" @tap="refund(selectedOrder)">申请退款</button></template><template v-else><button v-if="selectedOrder.status==='accepted'&&selectedOrder.refundStatus!=='pending'" class="primary" :disabled="busy" @tap="action('start')">开始服务</button><button v-if="selectedOrder.status==='serving'&&selectedOrder.refundStatus!=='pending'" class="primary" @tap="finish(selectedOrder)">提交完成</button></template></view></view>
      <view v-else-if="sheet==='refund' && selectedOrder" class="sheet-content"><view class="eyebrow">WE'RE HERE TO HELP</view><view class="sheet-title">申请售后退款</view><view class="sheet-sub">俱乐部会核实服务记录并处理你的申请。</view><view class="form-label">退款金额（元）</view><input v-model="refundAmount" class="form-input" type="digit"/><view class="input-help">最高可申请 ¥{{money(selectedOrder.amount)}}，支持部分退款。</view><view class="form-label">退款原因</view><textarea v-model="refundReason" class="text-area" placeholder="请说明遇到的问题，至少 5 个字" :maxlength="200"/><view class="simulation-note">提交后相关报酬会暂缓结算，等待后台审核。</view><button class="primary full" :disabled="busy" @tap="action('refund',selectedOrder,{amount:Math.round(Number(refundAmount)*100),reason:refundReason})">提交退款申请</button></view>
      <view v-else-if="sheet==='finish'" class="sheet-content"><view class="eyebrow">GG, WELL PLAYED</view><view class="sheet-title">提交服务记录</view><view class="sheet-sub">提交后由老板确认，随后报酬进入待结算。</view><view class="form-label">服务记录</view><textarea v-model="finishNote" class="text-area" placeholder="例如：已完成 2 小时陪玩，服务过程顺利。" :maxlength="200"/><button class="primary full" :disabled="busy" @tap="action('finish',selectedOrder,{note:finishNote})">提交完成</button></view>
      <view v-else-if="sheet==='help'" class="sheet-content"><view class="eyebrow">ALWAYS ON YOUR SIDE</view><view class="sheet-title">帮助与客服</view><view class="sheet-sub">这是前端演示环境，暂未接入真实客服。</view><view class="help-card"><uni-icons type="headphones" :size="35" color="#d9fd88"/><view><view>俱乐部客服工作台</view><text>订单、派单、退款都可以在 PC 后台处理。</text></view></view><button class="primary full" @tap="goAdmin">打开员工运营工作台 ↗</button><view class="sheet-footnote">同一浏览器两端共享模拟数据。跨标签页操作后可点击刷新查看变化；不同设备之间不共享。</view></view>
    </view></view>
    <view v-if="toast" class="toast"><uni-icons type="info" color="#d9fd88" :size="18"/>{{toast}}</view>
  </view>
</template>

<style lang="scss">
@import "../../styles/mobile.scss";
</style>
